// src/lib/filename.ts
function sanitizeFilename(name) {
  const s = (name ?? "").trim().replace(/[\\/:*?"<>|]/g, "").trim();
  return s || "\uC774\uB984\uC5C6\uB294\uC815\uC6D0";
}

// src/lib/exportDrawing.ts
function creditLines(file, withSatellite, today = /* @__PURE__ */ new Date()) {
  const vworld = file.place.basemap.provider === "vworld-satellite";
  const bg = withSatellite ? vworld ? "\uBC30\uACBD: \uBE0C\uC774\uC6D4\uB4DC(\uAD6D\uD1A0\uAD50\uD1B5\uBD80) \uC704\uC131\uC601\uC0C1" : `\uBC30\uACBD: ${file.place.basemap.attribution}` : "\uBC30\uACBD \uC704\uC131\uC601\uC0C1 \uC81C\uC678 (\uB3C4\uBA74\uB9CC)";
  const ph = file.photo?.visible ? ` \xB7 \uBC30\uACBD \uC0AC\uC9C4: \uC0AC\uC6A9\uC790 \uC81C\uACF5 (${file.photo.name})` : "";
  return [
    `${sanitizeFilename(file.meta.name)}${file.meta.author ? ` \xB7 \uC791\uC131\uC790 ${file.meta.author}` : ""} \xB7 ${today.toLocaleDateString("ko-KR")}`,
    `\uCD9C\uCC98: \uBE0C\uC774\uC6D4\uB4DC(\uAD6D\uD1A0\uAD50\uD1B5\uBD80) \xB7 ${bg}${ph} \xB7 \uAC1C\uC778 \uB2E4\uC6B4\uB85C\uB4DC\uC6A9, \uC11C\uBC84 \uC800\uC7A5 \uC5C6\uC74C`
  ];
}

// tests/photo.test.ts
var base = { id: "p", name: "drone.jpg", widthPx: 8e3, heightPx: 6e3, center: [127.11, 37.4], mPerPx: 0.03, rotationDeg: 12, opacity: 1, visible: true, source: "manual" };
var close = (a, b, eps, msg = "") => assert2(Math.abs(a - b) < eps, `${msg} ${a} vs ${b}`);
test("PNG/JPEG header dimensions without decoding", () => {
  const png = new Uint8Array(32);
  png.set([137, 80, 78, 71, 13, 10, 26, 10]);
  new DataView(png.buffer).setUint32(16, 8e3);
  new DataView(png.buffer).setUint32(20, 6e3);
  assert2.deepEqual(readImageDims(png), { width: 8e3, height: 6e3 });
  const jpg = new Uint8Array([255, 216, 255, 224, 0, 16, ...new Array(14).fill(0), 255, 192, 0, 17, 8, 23, 112, 31, 64, 3, 0, 0, 0, 0, 0, 0, 0, 0, 0]);
  assert2.deepEqual(readImageDims(jpg), { width: 8e3, height: 6e3 });
  assert2.equal(readImageDims(new Uint8Array([1, 2, 3])), null);
});
test("display downscale respects pixel cap and aspect", () => {
  const d = displaySize({ width: 8e3, height: 8e3 });
  assert2(d.width * d.height <= PHOTO_LIMITS.maxDisplayPixels);
  assert2.equal(d.width, d.height);
  assert2.deepEqual(displaySize({ width: 4e3, height: 3e3 }), { width: 4e3, height: 3e3 });
});
test("pxToMap / mapToPx round trip and ground scale", () => {
  for (const uv of [[0, 0], [8e3, 6e3], [1234, 4321]]) {
    const back = mapToPx(base, pxToMap(base, uv));
    close(back[0], uv[0], 1e-6);
    close(back[1], uv[1], 1e-6);
  }
  const a = pxToMap(base, [4e3, 3e3]), b = pxToMap(base, [5e3, 3e3]);
  const ground = Math.hypot(b[0] - a[0], b[1] - a[1]) * Math.cos(37.4 * Math.PI / 180);
  close(ground, 30, 0.01, "ground m");
  close(unitsPerPx(base), 0.03 / Math.cos(37.4 * Math.PI / 180), 1e-12);
});
test("2-point alignment recovers a known placement (scale, rotation, center)", () => {
  const truth = { ...base, center: [127.1123, 37.4011], mPerPx: 0.025, rotationDeg: -33 };
  const img = [[500, 700], [7400, 5200]];
  const map = img.map((u) => pxToMap(truth, u));
  const got = alignTwoPoints(base, img, map);
  close(got.mPerPx, 0.025, 1e-6, "mPerPx");
  close(got.rotationDeg, -33, 1e-3, "rot");
  close(got.center[0], 127.1123, 1e-9);
  close(got.center[1], 37.4011, 1e-9);
  assert2.equal(got.source, "2point");
  assert2.throws(() => alignTwoPoints(base, [[1, 1], [1, 1]], map));
});
test("fit to view centers image inside extent", () => {
  const c = fromLonLat2([127.11, 37.4]);
  const ext = [c[0] - 100, c[1] - 50, c[0] + 100, c[1] + 50];
  const p = fitToExtent(base, ext);
  close(p.center[0], 127.11, 1e-9);
  assert2.equal(p.rotationDeg, 0);
  const tl = pxToMap(p, [0, 0]), br = pxToMap(p, [8e3, 6e3]);
  assert2(tl[0] >= ext[0] && br[0] <= ext[2] && br[1] >= ext[1] && tl[1] <= ext[3]);
});
test("world file: WGS84 and Korean central TM (EPSG:5186) georeference", () => {
  const wf = parseWorldFile("0.000001\n0\n0\n-0.000001\n127.1\n37.41\n");
  assert2.equal(guessCrs(wf), "EPSG:4326");
  const p = placementFromWorldFile({ ...base, widthPx: 1e3, heightPx: 800 }, wf, "EPSG:4326");
  const tl = toLonLat2(pxToMap(p, [0.5, 0.5]));
  close(tl[0], 127.1, 1e-7);
  close(tl[1], 37.41, 1e-7);
  close(p.rotationDeg, 0, 0.01);
  const br = toLonLat2(pxToMap(p, [999.5, 799.5]));
  close(br[0], 127.1 + 999e-6, 1e-7);
  close(br[1], 37.41 - 799e-6, 1e-7);
  assert2(p.aspectY && Math.abs(p.aspectY - 1 / Math.cos(37.41 * Math.PI / 180)) < 0.01);
  const back = mapToPx(p, pxToMap(p, [10, 20]));
  close(back[1], 20, 1e-6);
  const [x, y] = (0, import_proj42.default)("EPSG:4326", "EPSG:5186", [127.1, 37.4]);
  const tm = parseWorldFile(`0.1
0
0
-0.1
${x}
${y}`);
  assert2.equal(guessCrs(tm), "EPSG:5186");
  const q = placementFromWorldFile({ ...base, widthPx: 2e3, heightPx: 2e3 }, tm, "EPSG:5186");
  close(q.mPerPx, 0.1, 2e-3, "TM m/px");
  const o = toLonLat2(pxToMap(q, [0.5, 0.5]));
  close(o[0], 127.1, 2e-6);
  close(o[1], 37.4, 2e-6);
  assert2.throws(() => parseWorldFile("1 2 3"));
});
test("scale bar reads 0.5 m / 1 m at high zoom", () => {
  assert2.equal(scaleBar(4e-3).label, "0.5 m");
  assert2.equal(scaleBar(8e-3).label, "1 m");
  assert2.equal(scaleBar(0.3).label, "20 m");
});
test("export credit names user photo", () => {
  const f = { schemaVersion: 1, meta: { name: "a", createdAt: "", updatedAt: "", northDeg: 0 }, place: { center: { lon: 0, lat: 0 }, zoom: 1, bbox: { west: 0, east: 0, north: 0, south: 0 }, basemap: { provider: "vworld-satellite", attribution: "" } }, features: [], photo: base };
  const l = creditLines(f, false)[1];
  assert2(l.includes("\uC0AC\uC6A9\uC790 \uC81C\uACF5 (drone.jpg)") && l.includes("\uBE0C\uC774\uC6D4\uB4DC(\uAD6D\uD1A0\uAD50\uD1B5\uBD80)"));
});
